import{_ as p,o as t,c as e,a0 as r}from"./chunks/framework.-mROjw-3.js";const h=JSON.parse('{"title":"卷积神经网络","description":"","frontmatter":{},"headers":[],"relativePath":"卷积神经网络.md","filePath":"卷积神经网络.md"}'),n={name:"卷积神经网络.md"};function o(s,a,d,i,_,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="卷积神经网络" tabindex="-1">卷积神经网络 <a class="header-anchor" href="#卷积神经网络" aria-label="Permalink to &quot;卷积神经网络&quot;">​</a></h1><p>这里简要阐述我对CNN的理解，日后如果时间充足，我可能会返回来补充。</p><h2 id="为什么不用全连接层而用cnn" tabindex="-1">为什么不用全连接层而用CNN <a class="header-anchor" href="#为什么不用全连接层而用cnn" aria-label="Permalink to &quot;为什么不用全连接层而用CNN&quot;">​</a></h2><p>卷积神经网络适用于图像处理，为什么不用全连接层呢？原因就是全连接层处理拉直后的图像，参数量巨大。因为全连接层往往吃的是一维度的，再接入全连接层，单纯第一层就已经参数很大了，多层的话参数直接爆炸。</p><p>所以决定使用卷积来处理图像。卷积层做的其实就是用一个卷积核（也叫滤波器），在要处理的图像上从左到右、从上到下滑动，反复识别局部模式。</p><p>卷积比全连接更好，因为卷积有几个突出的优点，比如参数共享，卷积核在扫图的过程中会将参数重复使用，对比全连接层，卷积层省参数特别多。</p><h2 id="填充和步幅" tabindex="-1">填充和步幅 <a class="header-anchor" href="#填充和步幅" aria-label="Permalink to &quot;填充和步幅&quot;">​</a></h2><p>填充：padding</p><p>填充其实就是把原来的图的外围填上一些像素，比如补0，这样可以保护我们内部的原图像，进而在经过卷积层时不丢失信息。</p><p>步幅：stride</p><p>卷积核每次移动的距离</p><p>步幅越大，输出越小，计算越快，信息损失越多。</p><p>CNN里面比较常见的配置：3×3卷积，padding = 1;stride = 1，原因很简单：卷积核小，参数少；padding = 1 能保持尺寸；stride = 1能够不丢失细节。</p><p>另外，输出大小由输入、padding、卷积核大小、步幅共同决定。</p><h2 id="多输入通道与多输出通道" tabindex="-1">多输入通道与多输出通道 <a class="header-anchor" href="#多输入通道与多输出通道" aria-label="Permalink to &quot;多输入通道与多输出通道&quot;">​</a></h2><p>真实的图片往往是多通道的，比如RGB彩色图像。</p><p>备考计算机二级的时候就经常接触RGB，大概意思就是你要定义一个颜色，其实是根据R、G、B三个通道来定义，所以每个像素点不是只有一个值，而是3个值一起描述颜色。</p><p><strong>卷积核其实是多层的</strong>，原因我在这里阐述一下：</p><p>正如上面所说，每个像素点其实是三个颜色的图层叠在一起组成的，就像一个有三层的汉堡，如果卷积核只是一个3×3的小方块，它就只能摸到最上面那一层，底下两层的信息就丢失了。</p><p>所以在面对彩色图片时，卷积核就不是二维的了，而是一个三维的小方块，可以滑动的小方块。</p><p><strong>一个卷积层通常有很多个卷积核</strong>，原因是因为一个卷积核只能提取一种特征倾向，每个卷积核都会输出一张特征图。所以<strong>输出通道数＝卷积核个数</strong>。</p><p><strong>输入通道数</strong>：输入数据本身的层数。</p><p>比如灰度图：1通道；</p><p>比如RGB图，就是3通道；</p><p>比如更复杂的图，可能通道数就更多。</p><p><strong>输出通道数</strong>：卷积核个数。</p>',26)])])}const g=p(n,[["render",o]]);export{h as __pageData,g as default};
